    parser.add_argument('--no-sub', action='store_true', help='Do not display subtitle banner')
    parser.add_argument('--center', '-c', action='store_true', help='Center horizontally in terminal')
    parser.add_argument('--no-sphere', '--text-only', action='store_true', help='Strip the circular sphere emblem, showing only IRIS typography')
    parser.add_argument('--interactive', '-i', action='store_true', help='Launch interactive menu')
    
    args = parser.parse_args()
    
    if args.interactive:
        interactive_menu()
    elif args.all:
        for t in ['iris', 'claude', 'cyberpunk', 'matrix', 'gold', 'original']:
            print(f"\n\033[1;33m>>> THEME: {t.upper()} (Ultra-HD {args.size.upper()}) <<<\033[0m")
            print_iris_logo(t, style=args.style, size=args.size, subtitle=not args.no_sub, center=args.center, no_sphere=args.no_sphere)
            print("-" * 90)
    elif args.animate:
        stream_iris_logo(args.theme, style=args.style, size=args.size, subtitle=not args.no_sub, center=args.center, no_sphere=args.no_sphere)
    else:
        print_iris_logo(args.theme, style=args.style, size=args.size, subtitle=not args.no_sub, center=args.center, no_sphere=args.no_sphere)
